        if (template !== undefined) syncSchedule(returned)
      }
      await props.refresh()
    }).catch((error: unknown) => {
      if (sequence === writeSequence.current) {
        const message = `Draft could not be updated: ${errorMessage(error)}`
        setSaveError(message)
        props.notify(message, 'error')
      }
    }).finally(() => {
      setPendingWrites((count) => Math.max(0, count - 1))
    })
    writeQueue.current = nextWrite
  }

reload = async () => {
    const ticket = ++request.current
    try {
      const next = await context.call(`${API}uiState`, {}) as AutomationUiState
      if (ticket !== request.current) return
      setState(previous => !previous || previous.revision <= next.revision ? next : previous)
      setError('')
    } catch (cause) { if (ticket === request.current) setError(message(cause)) }
  }

